-- What a user attached to a quick bug report: a screenshot and the technical context (page, recent errors, API calls).
-- Kept apart from the Issues table so the issue list stays light; one row per report.
CREATE TABLE "IssueDiagnostics" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "IssueId" integer NOT NULL,
    "UserId" text NOT NULL,
    "ContextJson" text NOT NULL,
    "Screenshot" bytea,
    "ScreenshotContentType" text,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "DeletedAt" timestamp with time zone,
    CONSTRAINT "PK_IssueDiagnostics" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_IssueDiagnostics_Issues_IssueId" FOREIGN KEY ("IssueId") REFERENCES "Issues" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_IssueDiagnostics_IssueId" ON "IssueDiagnostics" ("IssueId");
